#!/usr/bin/env python3
import sys, os, subprocess, tempfile, shutil
TPL="CB_BEGIN\n{{content}}\nCB_END\n"
def render(md, opts=None, raw=False, files=None, fmt='html'):
    opts = opts or []
    d = tempfile.mkdtemp(prefix="r", dir="/tmp/work/mdinl-xq7")
    open(os.path.join(d,"ch1.md"),"w",encoding='utf-8').write(md)
    open(os.path.join(d,"min.template"),"w",encoding='utf-8').write(TPL)
    lines=["author: A","title: T","lang: en","output.html: out.html",
           "html.standalone.template: min.template"]+list(opts)
    open(os.path.join(d,"book.book"),"w",encoding='utf-8').write("\n".join(lines)+"\n\n+ ch1.md\n")
    for name,content in (files or {}).items():
        p=os.path.join(d,name)
        os.makedirs(os.path.dirname(p), exist_ok=True) if os.path.dirname(name) else None
        if isinstance(content,bytes): open(p,'wb').write(content)
        else: open(p,"w",encoding='utf-8').write(content)
    r=subprocess.run(["/tmp/ref/crowbook","-q","book.book"],cwd=d,capture_output=True,text=True)
    err=(r.stdout+r.stderr).strip()
    try:
        s=open(os.path.join(d,"out.html"),encoding='utf-8').read()
    except Exception:
        return ("<<NOOUTPUT>> "+err, d)
    i=s.find("CB_BEGIN"); j=s.find("CB_END")
    body=s[i+9:j] if i>=0 and j>=0 else s
    if err: body = body + "\n<<STDERR>> "+err
    return (body, d)

if __name__=="__main__":
    import argparse
    ap=argparse.ArgumentParser()
    ap.add_argument("-o","--opt",action="append",default=[])
    ap.add_argument("-r","--raw",action="store_true")
    ap.add_argument("-k","--keep",action="store_true")
    a=ap.parse_args()
    md=sys.stdin.read()
    body,d=render(md,a.opt)
    if a.raw: print(repr(body))
    else: print(body)
    if a.keep: print("DIR="+d, file=sys.stderr)
PY
